"use client";

import {
  AlertCircle,
  ExternalLink,
  Loader2,
  Monitor,
  RefreshCw,
  Smartphone,
  Tablet,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";
import type { PreviewStatus, RuntimeError, ViewportSize } from "@/lib/sandbox/types";
import { getViewportWidth, sandboxPanelClassName } from "@/lib/sandbox/utils";
import { ErrorOverlay } from "./error-overlay";

interface PreviewFrameProps {
  status: PreviewStatus;
  viewport: ViewportSize;
  onViewportChange: (viewport: ViewportSize) => void;
  srcDoc: string;
  runtimeError?: RuntimeError | null;
  onRefresh?: () => void;
  onOpenInNewTab?: () => void;
  onOpenErrorFile?: () => void;
  onDismissError?: () => void;
  className?: string;
}

const viewportOptions: {
  value: ViewportSize;
  label: string;
  icon: typeof Monitor;
}[] = [
  { value: "desktop", label: "Desktop", icon: Monitor },
  { value: "tablet", label: "Tablet", icon: Tablet },
  { value: "mobile", label: "Mobile", icon: Smartphone },
];

export function PreviewFrame({
  status,
  viewport,
  onViewportChange,
  srcDoc,
  runtimeError,
  onRefresh,
  onOpenInNewTab,
  onOpenErrorFile,
  onDismissError,
  className,
}: PreviewFrameProps) {
  return (
    <div className={sandboxPanelClassName(className)}>
      <div className="flex items-center justify-between border-b border-white/[0.06] bg-[#101012] px-3 py-2">
        <div className="flex items-center gap-2">
          <span className="text-[11px] font-medium uppercase tracking-[0.12em] text-zinc-500">
            Preview
          </span>
          {status === "loading" ? (
            <span className="inline-flex items-center gap-1 text-[11px] text-muted-foreground">
              <Loader2 className="size-3 animate-spin" />
              Building...
            </span>
          ) : null}
          {status === "error" ? (
            <span className="inline-flex items-center gap-1 text-[11px] text-destructive">
              <AlertCircle className="size-3" />
              Error
            </span>
          ) : null}
        </div>
        <div className="flex items-center gap-1">
          <div className="mr-1 flex items-center rounded-lg border border-border/50 p-0.5">
            {viewportOptions.map(({ value, label, icon: Icon }) => (
              <Tooltip key={value}>
                <TooltipTrigger
                  render={
                    <Button
                      variant={viewport === value ? "secondary" : "ghost"}
                      size="icon-xs"
                      onClick={() => onViewportChange(value)}
                      aria-label={label}
                    />
                  }
                >
                  <Icon />
                </TooltipTrigger>
                <TooltipContent>{label}</TooltipContent>
              </Tooltip>
            ))}
          </div>
          {onRefresh ? (
            <Tooltip>
              <TooltipTrigger
                render={
                  <Button variant="ghost" size="icon-xs" onClick={onRefresh} />
                }
              >
                <RefreshCw />
              </TooltipTrigger>
              <TooltipContent>Refresh preview</TooltipContent>
            </Tooltip>
          ) : null}
          {onOpenInNewTab ? (
            <Tooltip>
              <TooltipTrigger
                render={
                  <Button
                    variant="ghost"
                    size="icon-xs"
                    onClick={onOpenInNewTab}
                  />
                }
              >
                <ExternalLink />
              </TooltipTrigger>
              <TooltipContent>Open in new tab</TooltipContent>
            </Tooltip>
          ) : null}
        </div>
      </div>
      <div className="relative flex min-h-[320px] flex-1 items-start justify-center bg-[#09090b] p-4 [background-image:radial-gradient(rgba(255,255,255,0.04)_1px,transparent_1px)] [background-size:16px_16px]">
        {status === "loading" ? (
          <div className="absolute inset-0 z-10 flex items-center justify-center bg-background/60 backdrop-blur-[1px]">
            <div className="flex flex-col items-center gap-3">
              <Loader2 className="size-5 animate-spin text-muted-foreground" />
              <p className="text-xs text-muted-foreground">
                Rebuilding preview...
              </p>
            </div>
          </div>
        ) : null}

        {status === "error" && !runtimeError ? (
          <div className="flex flex-col items-center justify-center gap-2 py-16 text-center">
            <AlertCircle className="size-8 text-destructive/80" />
            <p className="text-sm font-medium">Preview failed to load</p>
            <p className="max-w-xs text-xs text-muted-foreground">
              Check the console for build errors and try running again.
            </p>
          </div>
        ) : (
          <div
            className={cn(
              "relative h-[420px] overflow-hidden rounded-lg border border-border/50 bg-white shadow-2xl transition-all duration-300",
              viewport !== "desktop" && "mx-auto"
            )}
            style={{ width: getViewportWidth(viewport), maxWidth: "100%" }}
          >
            <iframe
              title="Preview"
              srcDoc={srcDoc}
              sandbox="allow-scripts allow-same-origin"
              className="h-full w-full border-0 bg-white"
            />
            {runtimeError ? (
              <ErrorOverlay
                error={runtimeError}
                onOpenFile={onOpenErrorFile}
                onCopy={async () => {
                  const { formatRuntimeErrorForCopy } = await import(
                    "@/lib/sandbox/utils"
                  );
                  await navigator.clipboard.writeText(
                    formatRuntimeErrorForCopy(runtimeError)
                  );
                }}
                onDismiss={onDismissError}
              />
            ) : null}
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { AlertCircle, Copy, ExternalLink, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import type { RuntimeError } from "@/lib/sandbox/types";

interface ErrorOverlayProps {
  error: RuntimeError;
  onOpenFile?: () => void;
  onCopy?: () => void | Promise<void>;
  onDismiss?: () => void;
}

export function ErrorOverlay({
  error,
  onOpenFile,
  onCopy,
  onDismiss,
}: ErrorOverlayProps) {
  const [copied, setCopied] = useState(false);

  const handleCopy = async () => {
    await onCopy?.();
    setCopied(true);
    window.setTimeout(() => setCopied(false), 1500);
  };

  return (
    <div className="absolute inset-0 z-20 flex flex-col bg-zinc-950/95 backdrop-blur-sm">
      <div className="flex items-center justify-between border-b border-red-500/20 bg-red-500/10 px-4 py-3">
        <div className="flex items-center gap-2">
          <AlertCircle className="size-4 text-red-400" />
          <div>
            <p className="text-sm font-medium text-red-100">{error.title}</p>
            <p className="text-xs text-red-200/80">{error.message}</p>
          </div>
        </div>
        {onDismiss ? (
          <Button variant="ghost" size="icon-xs" onClick={onDismiss}>
            <X />
          </Button>
        ) : null}
      </div>
      <div className="flex-1 overflow-auto p-4">
        <p className="mb-3 font-mono text-xs text-muted-foreground">
          {error.file}:{error.line}
          {error.column ? `:${error.column}` : ""}
        </p>
        <pre className="whitespace-pre-wrap rounded-lg border border-border/50 bg-black/40 p-3 font-mono text-[11px] leading-relaxed text-red-100/90">
          {error.stack}
        </pre>
      </div>
      <div className="flex items-center gap-2 border-t border-border/50 px-4 py-3">
        {onOpenFile ? (
          <Button variant="outline" size="sm" onClick={onOpenFile}>
            <ExternalLink />
            Open file
          </Button>
        ) : null}
        {onCopy ? (
          <Button variant="outline" size="sm" onClick={handleCopy}>
            <Copy />
            {copied ? "Copied" : "Copy error"}
          </Button>
        ) : null}
      </div>
    </div>
  );
}

export type ViewportSize = "desktop" | "tablet" | "mobile";
export type ConsoleLevel = "log" | "info" | "warn" | "error";
export type PreviewStatus = "idle" | "loading" | "ready" | "error";

export interface SandboxFile {
  id: string;
  name: string;
  path: string;
  language: "tsx" | "ts" | "css" | "json";
  content: string;
  isDirty?: boolean;
}

export interface ConsoleMessage {
  id: string;
  level: ConsoleLevel;
  message: string;
  timestamp: Date;
  source?: string;
}

export interface PackageInstallEvent {
  id: string;
  name: string;
  version: string;
  status: "pending" | "success" | "error";
  output?: string;
}

export interface RuntimeError {
  title: string;
  message: string;
  stack: string;
  file: string;
  line: number;
  column?: number;
}

export interface FileTreeNode {
  id: string;
  name: string;
  type: "file" | "folder";
  children?: FileTreeNode[];
  fileId?: string;
}

export interface SandboxState {
  files: SandboxFile[];
  originalContents: Record<string, string>;
  activeFileId: string;
  fileTree: FileTreeNode[];
  consoleMessages: ConsoleMessage[];
  installEvents: PackageInstallEvent[];
  runtimeError: RuntimeError | null;
  previewStatus: PreviewStatus;
  viewport: ViewportSize;
  previewSrcDoc: string;
  consoleCollapsed: boolean;
}

import type { FileTreeNode, SandboxFile } from "./types";

export function getLanguageLabel(language: SandboxFile["language"]): string {
  const labels: Record<SandboxFile["language"], string> = {
    tsx: "TypeScript React",
    ts: "TypeScript",
    css: "CSS",
    json: "JSON",
  };
  return labels[language];
}

export function getLanguageBadge(language: SandboxFile["language"]): string {
  const badges: Record<SandboxFile["language"], string> = {
    tsx: "TSX",
    ts: "TS",
    css: "CSS",
    json: "JSON",
  };
  return badges[language];
}

export function formatTimestamp(date: Date): string {
  return date.toLocaleTimeString("en-US", {
    hour12: false,
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
}

export function formatCode(content: string): string {
  const lines = content.split("\n");
  let indent = 0;
  const formatted: string[] = [];

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) {
      formatted.push("");
      continue;
    }

    if (/^[\}\]\)]/.test(trimmed)) {
      indent = Math.max(0, indent - 1);
    }

    formatted.push(`${"  ".repeat(indent)}${trimmed}`);

    const openBrackets = (trimmed.match(/[\{\[\(]/g) || []).length;
    const closeBrackets = (trimmed.match(/[\}\]\)]/g) || []).length;
    indent += openBrackets - closeBrackets;
    indent = Math.max(0, indent);
  }

  return formatted.join("\n");
}

export function findFileIdInTree(
  nodes: FileTreeNode[],
  fileId: string
): string | null {
  for (const node of nodes) {
    if (node.type === "file" && node.fileId === fileId) {
      return node.id;
    }
    if (node.children) {
      const found = findFileIdInTree(node.children, fileId);
      if (found) return found;
    }
  }
  return null;
}

export function removeFileFromTree(
  nodes: FileTreeNode[],
  fileId: string
): FileTreeNode[] {
  return nodes
    .filter((node) => !(node.type === "file" && node.fileId === fileId))
    .map((node) =>
      node.children
        ? { ...node, children: removeFileFromTree(node.children, fileId) }
        : node
    );
}

export function addFileToTree(
  nodes: FileTreeNode[],
  file: SandboxFile
): FileTreeNode[] {
  const parts = file.path.split("/");
  if (parts.length === 1) {
    return [
      ...nodes,
      {
        id: `tree-${file.id}`,
        name: file.name,
        type: "file" as const,
        fileId: file.id,
      },
    ];
  }

  const [folderName, ...rest] = parts;
  const folderId = `folder-${folderName}`;
  const existingFolderIndex = nodes.findIndex(
    (node) => node.type === "folder" && node.name === folderName
  );

  if (existingFolderIndex >= 0) {
    const folder = nodes[existingFolderIndex];
    const updatedFolder: FileTreeNode = {
      ...folder,
      children: addFileToTree(folder.children ?? [], {
        ...file,
        path: rest.join("/"),
      }),
    };
    return nodes.map((node, index) =>
      index === existingFolderIndex ? updatedFolder : node
    );
  }

  return [
    ...nodes,
    {
      id: folderId,
      name: folderName,
      type: "folder" as const,
      children: addFileToTree([], { ...file, path: rest.join("/") }),
    },
  ];
}

export function sandboxPanelClassName(className?: string): string {
  return [
    "overflow-hidden rounded-xl border border-white/[0.06] bg-[#101012]/90",
    className,
  ]
    .filter(Boolean)
    .join(" ");
}

export function getViewportWidth(viewport: "desktop" | "tablet" | "mobile") {
  const widths = {
    desktop: "100%",
    tablet: "768px",
    mobile: "390px",
  } as const;
  return widths[viewport];
}

export function formatRuntimeErrorForCopy(error: {
  title: string;
  message: string;
  stack: string;
  file: string;
  line: number;
  column?: number;
}): string {
  return `${error.title}: ${error.message}
at ${error.file}:${error.line}${error.column ? `:${error.column}` : ""}

${error.stack}`;
}
